/**
 * verify-schema-drift.ts — Issue #1586 (BE-014)
 *
 * Shadow-database schema drift + rollback verification for CI.
 *
 * Against a clean, disposable PostgreSQL database (DRIFT_DATABASE_URL) it:
 *  1. Resets the database to an empty `public` schema.
 *  2. Applies every migration in `prisma/migrations` sequentially. After each
 *     one it rolls the migration back — using the migration's own `down.sql`
 *     when present, otherwise a down script generated by diffing the database
 *     against the prior migration history — and checks that the database
 *     schema is identical to the snapshot taken before the migration ran.
 *     The migration is then re-applied and the loop continues.
 *  3. Compares the fully migrated database against `prisma/schema.prisma`.
 *
 * Any drift or unclean rollback exits non-zero and writes a detailed report
 * (default `schema-drift-report.md`, override with SCHEMA_DRIFT_REPORT).
 *
 * Usage (from backend/):
 *   DRIFT_DATABASE_URL=postgresql://... SHADOW_DATABASE_URL=postgresql://... \
 *     npm run schema:verify-drift
 *
 * Flags:
 *   --skip-rollback   only apply migrations and check drift against schema.prisma
 */

import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const BACKEND_ROOT = process.cwd();
const MIGRATIONS_DIR = join(BACKEND_ROOT, 'prisma', 'migrations');
const SCHEMA_PATH = join(BACKEND_ROOT, 'prisma', 'schema.prisma');
const REPORT_PATH = process.env.SCHEMA_DRIFT_REPORT || join(BACKEND_ROOT, 'schema-drift-report.md');

const RESET_SQL = 'DROP SCHEMA IF EXISTS "public" CASCADE;\nCREATE SCHEMA "public";\n';

export interface RollbackFailure {
  migration: string;
  source: 'down.sql' | 'generated';
  diff: string;
}

export interface DriftReport {
  migrationsApplied: string[];
  rollbackFailures: RollbackFailure[];
  driftScript: string;
  errors: string[];
}

interface PrismaResult {
  status: number;
  stdout: string;
  stderr: string;
}

interface Databases {
  targetUrl: string;
  shadowUrl: string;
}

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    console.error(`[schema-drift] ${name} must be set to a disposable PostgreSQL database`);
    process.exit(1);
  }
  return value;
}

/**
 * Run a Prisma CLI command against the drift database. `prisma.config.ts`
 * reads DATABASE_URL / SHADOW_DATABASE_URL, so we point those at the
 * disposable databases instead of whatever the caller's environment uses.
 */
function prisma(args: string[], dbs: Databases): PrismaResult {
  const result = spawnSync('npx', ['prisma', ...args], {
    cwd: BACKEND_ROOT,
    env: { ...process.env, DATABASE_URL: dbs.targetUrl, SHADOW_DATABASE_URL: dbs.shadowUrl },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
    shell: process.platform === 'win32',
  });
  return {
    status: result.status ?? 1,
    stdout: result.stdout ?? '',
    stderr: result.stderr || (result.error ? String(result.error) : ''),
  };
}

function prismaOrThrow(args: string[], dbs: Databases): string {
  const result = prisma(args, dbs);
  if (result.status !== 0) {
    throw new Error(`prisma ${args.join(' ')} exited ${result.status}: ${result.stderr.trim()}`);
  }
  return result.stdout;
}

function executeFile(file: string, dbs: Databases): void {
  prismaOrThrow(['db', 'execute', '--file', file], dbs);
}

function resetDatabase(workDir: string, dbs: Databases): void {
  const file = join(workDir, 'reset.sql');
  writeFileSync(file, RESET_SQL);
  executeFile(file, dbs);
}

/**
 * Canonical DDL for the current database schema. Prisma renders the diff from
 * an empty schema deterministically, so two snapshots are identical iff the
 * schemas (tables, columns, types, defaults, indexes, constraints, enums) are.
 */
function snapshotSchema(dbs: Databases): string {
  return prismaOrThrow(['migrate', 'diff', '--from-empty', '--to-config-datasource', '--script'], dbs).trim();
}

export function listMigrations(dir: string = MIGRATIONS_DIR): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(dir, d.name, 'migration.sql')))
    .map((d) => d.name)
    .sort();
}

/** Minimal line diff (LCS) so the report shows exactly what changed. */
export function lineDiff(before: string, after: string): string {
  const a = before.split('\n');
  const b = after.split('\n');
  const dp: number[][] = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const out: string[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      out.push(`- ${a[i++]}`);
    } else {
      out.push(`+ ${b[j++]}`);
    }
  }
  while (i < a.length) out.push(`- ${a[i++]}`);
  while (j < b.length) out.push(`+ ${b[j++]}`);
  return out.join('\n');
}

/** Copy migration_lock.toml plus the first `count` migrations into a temp dir. */
function stageMigrations(names: string[], count: number, workDir: string): string {
  const keep = new Set(['migration_lock.toml', ...names.slice(0, count)]);
  const staged = join(workDir, `migrations-${count}`);
  rmSync(staged, { recursive: true, force: true });
  cpSync(MIGRATIONS_DIR, staged, {
    recursive: true,
    filter: (src) => {
      const rel = src.slice(MIGRATIONS_DIR.length).replace(/^[\\/]/, '');
      return rel === '' || keep.has(rel.split(/[\\/]/)[0]);
    },
  });
  return staged;
}

function resolveDownScript(
  names: string[],
  index: number,
  workDir: string,
  dbs: Databases
): { file: string; source: RollbackFailure['source'] } {
  const name = names[index];
  const handWritten = join(MIGRATIONS_DIR, name, 'down.sql');
  if (existsSync(handWritten)) {
    return { file: handWritten, source: 'down.sql' };
  }

  const previous = stageMigrations(names, index, workDir);
  const script = prismaOrThrow(
    ['migrate', 'diff', '--from-config-datasource', '--to-migrations', previous, '--script'],
    dbs
  );
  const file = join(workDir, `${name}.down.sql`);
  writeFileSync(file, script);
  return { file, source: 'generated' };
}

function hasFailures(report: DriftReport): boolean {
  return report.errors.length > 0 || report.rollbackFailures.length > 0 || report.driftScript !== '';
}

export function renderReport(report: DriftReport): string {
  const lines: string[] = ['# Schema Drift Report', ''];
  lines.push(`**Status:** ${hasFailures(report) ? '❌ drift detected' : '✅ no drift detected'}`, '');
  lines.push(`Migrations applied to shadow database: ${report.migrationsApplied.length}`, '');

  if (report.errors.length > 0) {
    lines.push('## Errors', '');
    for (const err of report.errors) lines.push('```', err, '```', '');
  }

  if (report.rollbackFailures.length > 0) {
    lines.push('## Rollbacks that did not restore the prior schema', '');
    lines.push('`-` = present before the migration but missing after rollback; `+` = left behind by rollback.', '');
    for (const failure of report.rollbackFailures) {
      lines.push(`### ${failure.migration} (${failure.source})`, '');
      lines.push('```diff', failure.diff, '```', '');
    }
  }

  if (report.driftScript) {
    lines.push('## Un-migrated changes in schema.prisma', '');
    lines.push(
      'Applying every migration does not produce the schema described by `prisma/schema.prisma`. ' +
        'Create a migration (`npx prisma migrate dev --name <change>`) containing:',
      ''
    );
    lines.push('```sql', report.driftScript, '```', '');
  }

  return lines.join('\n');
}

export function verifySchemaDrift(options: { skipRollback: boolean }): DriftReport {
  const dbs: Databases = {
    targetUrl: requireEnv('DRIFT_DATABASE_URL'),
    shadowUrl: requireEnv('SHADOW_DATABASE_URL'),
  };
  if (dbs.targetUrl === dbs.shadowUrl) {
    console.error('[schema-drift] DRIFT_DATABASE_URL and SHADOW_DATABASE_URL must be different databases');
    process.exit(1);
  }

  const report: DriftReport = { migrationsApplied: [], rollbackFailures: [], driftScript: '', errors: [] };
  const workDir = mkdtempSync(join(tmpdir(), 'schema-drift-'));
  const names = listMigrations();

  try {
    console.log('[schema-drift] Resetting drift database to an empty public schema...');
    resetDatabase(workDir, dbs);

    for (let i = 0; i < names.length; i++) {
      const name = names[i];
      const migrationFile = join(MIGRATIONS_DIR, name, 'migration.sql');
      const before = options.skipRollback ? '' : snapshotSchema(dbs);

      console.log(`[schema-drift] (${i + 1}/${names.length}) applying ${name}`);
      executeFile(migrationFile, dbs);
      report.migrationsApplied.push(name);

      if (options.skipRollback) continue;

      const down = resolveDownScript(names, i, workDir, dbs);
      console.log(`[schema-drift]   rolling back ${name} using ${down.source} script`);
      executeFile(down.file, dbs);

      const after = snapshotSchema(dbs);
      if (after !== before) {
        report.rollbackFailures.push({ migration: name, source: down.source, diff: lineDiff(before, after) });
        console.error(`[schema-drift]   ✗ rollback of ${name} did not restore the prior schema`);
        // Rebuild the exact prior state so later migrations are checked
        // against a correct baseline instead of cascading this failure.
        resetDatabase(workDir, dbs);
        for (const prior of names.slice(0, i)) {
          executeFile(join(MIGRATIONS_DIR, prior, 'migration.sql'), dbs);
        }
      }

      executeFile(migrationFile, dbs);
    }

    console.log('[schema-drift] Comparing migrated database against prisma/schema.prisma...');
    const drift = prisma(
      ['migrate', 'diff', '--from-config-datasource', '--to-schema', SCHEMA_PATH, '--script', '--exit-code'],
      dbs
    );
    // --exit-code: 0 = no difference, 2 = difference, anything else = error.
    if (drift.status === 2) {
      report.driftScript = drift.stdout.trim();
    } else if (drift.status !== 0) {
      report.errors.push(`prisma migrate diff exited ${drift.status}: ${drift.stderr.trim()}`);
    }
  } catch (err) {
    report.errors.push((err as Error).message);
  } finally {
    rmSync(workDir, { recursive: true, force: true });
  }

  return report;
}

const isDirectRun =
  typeof process.argv[1] === 'string' && process.argv[1].endsWith('verify-schema-drift.ts');

if (isDirectRun) {
  const report = verifySchemaDrift({ skipRollback: process.argv.includes('--skip-rollback') });
  const rendered = renderReport(report);
  writeFileSync(REPORT_PATH, rendered);

  if (hasFailures(report)) {
    console.error(rendered);
    console.error(`[schema-drift] ✗ Drift detected. Full report written to ${REPORT_PATH}`);
    process.exit(1);
  }
  console.log(
    `[schema-drift] ✓ ${report.migrationsApplied.length} migrations applied, rolled back and re-applied cleanly; ` +
      'no drift from schema.prisma.'
  );
}
